import { Fragment, type ReactNode } from "react";
import { cn } from "@/lib/cn";

// One per day on the Week screen. Not interactive itself; the cooked tick (blocked)
// is a slot the consumer fills, and only passed and today rows have one. Zones differ by surface and border, never hue alone.

type Base = {
  /** Weekday and date as the consumer formats it. */
  label: string;
  labelLang?: string;
  mainMeal?: string;
  mainMealLang?: string;
  /** The other three slots. */
  summary?: string[];
  className?: string;
};
export type DayRowProps = Base &
  (
    | { variant: "passed" | "today"; /** The cooked tick for the main meal.*/ tick?: ReactNode; todayWord?: string }
    | { variant: "ahead" | "draft"; tick?: never; todayWord?: never }
  );

const variants = {
  // every variant keeps the same outer size: borders differ in width, padding compensates
  passed: "border-bw-default border-border bg-surface-sunken p-inset-md",
  today: "border-bw-heavy border-primary-text bg-surface-raised p-row-today",
  ahead: "border-bw-default border-border-card bg-surface-raised p-inset-md",
  draft: "border-bw-default border-dashed border-border-strong bg-surface-sunken p-inset-md",
} as const;

export function DayRow({ variant, label, labelLang, mainMeal, mainMealLang, summary = [], tick, todayWord = "Today", className }: DayRowProps) {
  const isToday = variant === "today";
  return (
    <li
      aria-current={isToday ? "date" : undefined}
      className={cn("flex items-center gap-gap-md rounded-card font-body leading-normal", variants[variant], className)}
    >
      <div className="flex min-w-0 flex-1 flex-col">
        <span
          lang={labelLang}
          className={cn(
            "text-ui-floor font-label [overflow-wrap:anywhere] latin:uppercase latin:tracking-label",
            isToday ? "text-primary-text" : "text-text-muted",
          )}
        >
          {isToday ? `${todayWord}, ${label}` : label}
        </span>
        {mainMeal && (
          <span lang={mainMealLang} className="text-ui-body font-medium text-text [overflow-wrap:anywhere]">
            {mainMeal}
          </span>
        )}
        {summary.length > 0 && (
          <span className="text-ui-floor font-regular text-text-muted [overflow-wrap:anywhere]">
            {summary.map((item, i) => (
              <Fragment key={i}>
                {i > 0 && (
                  <>
                    {" "}
                    <span aria-hidden="true">·</span>{" "}
                  </>
                )}
                <span>
                  {item}
                  {i < summary.length - 1 && <span className="[clip-path:inset(50%)]">,</span>}
                </span>
              </Fragment>
            ))}
          </span>
        )}
      </div>
      {tick && <div className="shrink-0">{tick}</div>}
    </li>
  );
}

/** The seven rows: a real list. */
export function DayRowList({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <ul role="list" className={cn("flex flex-col gap-stack-sm", className)}>
      {children}
    </ul>
  );
}
